#include <iostream>
struct Node {
    int value;
    Node* next;
};
Node* make(int value, Node* next) {
    Node* node = new Node{};
    node->value = value;
    node->next = next;
    return node;
}
void print(Node* head) {
    for (Node* p = head; p != nullptr; p = p->next) {
        std::cout << p->value << " ";
    }
    std::cout << "\n";
}
int main() {
    int a;
    int b;
    int c;
    std::cin >> a >> b >> c;
    Node* tail = make(c, nullptr);
    Node* middle = make(b, tail);
    Node* head = make(a, middle);
    print(head);
    head->next = tail;
    delete middle;
    print(head);
    delete head;
    delete tail;
    return 0;
}

#include <stdio.h>
int main(void) {
    int n = 7;
    int values[7] = {7, -3, 0, 5, -3, 2, 9};
    for (int end = n - 1; end > 0; end = end - 1) {
        for (int j = 0; j < end; j = j + 1) {
            if (values[j] > values[j + 1]) {
                int temp = values[j];
                values[j] = values[j + 1];
                values[j + 1] = temp;
            }
        }
    }
    for (int i = 0; i < n; i = i + 1) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", values[i]);
    }
    printf("\n");
    return 0;
}
